// Refresh access token if expired
const cfg = $json;
const now = Date.now();
const expiry = cfg.gmail_token_expiry ? new Date(cfg.gmail_token_expiry).getTime() : 0;
let accessToken = cfg.gmail_access_token;
if (!accessToken || expiry < now + 30000) {
  const refresh = cfg.gmail_refresh_token;
  if (!refresh) return [{ json: { ...cfg, _skip: true } }];
  const r = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://oauth2.googleapis.com/token',
    body: new URLSearchParams({
      client_id: $env.GOOGLE_CLIENT_ID,
      client_secret: $env.GOOGLE_CLIENT_SECRET,
      refresh_token: refresh,
      grant_type: 'refresh_token',
    }).toString(),
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    json: true,
  });
  accessToken = r.access_token;
  // Persist back
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `https://auth.purama.dev/rest/v1/email_agent_config?user_id=eq.${cfg.user_id}`,
    headers: {
      apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
      Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
      'Content-Profile': 'purama_ai',
      'Content-Type': 'application/json',
      Prefer: 'return=minimal',
    },
    body: { gmail_access_token: accessToken, gmail_token_expiry: new Date(Date.now() + (r.expires_in - 60) * 1000).toISOString() },
  });
}
return [{ json: { ...cfg, _accessToken: accessToken } }];

const cfg = $('Refresh Gmail token').item.json;
const messages = $json.messages || [];
return messages.map(m => ({ json: { ...cfg, message_id: m.id, thread_id: m.threadId } }));

// Parse Gmail message + extract from/subject/body
const cfg = $('Explode messages').item.json;
const msg = $json;
const headers = (msg.payload?.headers ?? []).reduce((acc, h) => { acc[h.name.toLowerCase()] = h.value; return acc; }, {});
const fromHeader = headers.from || '';
const match = fromHeader.match(/(.*?)<(.+?)>/) || [null, null, fromHeader];
const from_name = (match[1] || '').replace(/"/g, '').trim() || null;
const from_email = (match[2] || fromHeader).trim();
const subject = headers.subject || '';

// Decode body (text/plain preferred)
function findPart(parts, mime) {
  for (const p of parts || []) {
    if (p.mimeType === mime && p.body?.data) return p.body.data;
    if (p.parts) { const r = findPart(p.parts, mime); if (r) return r; }
  }
  return null;
}
let body = '';
if (msg.payload?.body?.data) body = msg.payload.body.data;
else body = findPart(msg.payload?.parts, 'text/plain') || findPart(msg.payload?.parts, 'text/html') || '';
if (body) body = Buffer.from(body.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf-8');
body = body.replace(/<[^>]+>/g, '').slice(0, 4000);

return [{ json: { ...cfg, gmail_message_id: msg.id, gmail_thread_id: msg.threadId, snippet: msg.snippet, from_name, from_email, subject, body_preview: body.slice(0, 600), body_full: body, received_at: new Date(parseInt(msg.internalDate)).toISOString() } }];

