const ctx = $('Parse message').item.json;
const raw = $json.content?.[0]?.text || '{}';
let analysis = {};
try {
  const m = raw.match(/\{[\s\S]*\}/);
  analysis = JSON.parse(m ? m[0] : raw);
} catch { analysis = { category: 'normal', intention: 'autre', action: 'notify', confidence: 0.3, reasoning: 'parse error' }; }
return [{ json: { ...ctx, analysis, tokens_used: ($json.usage?.input_tokens || 0) + ($json.usage?.output_tokens || 0) } }];
